package com.calculadora.vista;
import javax.swing.*;
import javax.swing.border.*;
import javax.swing.plaf.basic.*;
import java.awt.*;
public final class EstiloModerno {
 private EstiloModerno(){}
 public static void instalar(){Font f=new Font("SansSerif",Font.PLAIN,13);for(Object k:java.util.Collections.list(UIManager.getDefaults().keys()))if(k.toString().endsWith(".font"))UIManager.put(k,new javax.swing.plaf.FontUIResource(f));UIManager.put("control",new Color(247,247,252));UIManager.put("nimbusBase",new Color(111,76,192));UIManager.put("nimbusFocus",new Color(157,118,242));UIManager.put("text",new Color(41,38,61));UIManager.put("MenuBar.background",Color.WHITE);UIManager.put("ScrollPane.border",new EmptyBorder(0,0,0,0));UIManager.put("TabbedPane.contentMargins",new Insets(8,0,0,0));}
 public static void campo(JTextField f){f.setBackground(new Color(247,247,253));f.setForeground(new Color(41,38,61));f.setCaretColor(new Color(109,67,204));f.setFont(new Font("SansSerif",Font.PLAIN,14));f.setBorder(new CompoundBorder(new LineBorder(new Color(219,215,234),1,true),new EmptyBorder(10,12,10,12)));}
 public static void combo(JComboBox<String> c){c.setUI(new BasicComboBoxUI(){protected JButton createArrowButton(){JButton b=new JButton("⌄");b.setBorder(new EmptyBorder(0,7,0,7));b.setContentAreaFilled(false);b.setForeground(new Color(112,75,182));return b;}});if(c.getItemCount()>0&&String.valueOf(c.getItemAt(0)).length()<3)c.setPreferredSize(new Dimension(76,36));c.setBackground(new Color(247,247,253));c.setForeground(new Color(41,38,61));c.setBorder(new CompoundBorder(new LineBorder(new Color(226,221,239),1,true),new EmptyBorder(5,8,5,3)));}
 public static void pestanas(JTabbedPane p){p.setUI(new BasicTabbedPaneUI(){protected void installDefaults(){super.installDefaults();tabInsets=new Insets(10,17,10,17);contentBorderInsets=new Insets(8,0,0,0);selectedTabPadInsets=new Insets(0,0,0,0);tabAreaInsets=new Insets(0,0,0,0);}protected void paintTab(Graphics g,int place,Rectangle[] rects,int index,Rectangle icon,Rectangle text){Rectangle r=rects[index];paintTabBackground(g,place,index,r.x,r.y,r.width,r.height,index==tabPane.getSelectedIndex());super.paintTab(g,place,rects,index,icon,text); }protected void paintTabBackground(Graphics g,int place,int index,int x,int y,int w,int h,boolean selected){Graphics2D a=(Graphics2D)g.create();a.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);a.setColor(selected?new Color(111,67,198):new Color(234,228,246));a.fillRoundRect(x,y,w-5,h-2,16,16);a.dispose();}protected void paintTabBorder(Graphics g,int p,int i,int x,int y,int w,int h,boolean s){}protected void paintFocusIndicator(Graphics g,int p,Rectangle[] r,int i,Rectangle icon,Rectangle text,boolean selected){if(selected&&tabPane.hasFocus()){g.setColor(Color.WHITE);g.drawRect(text.x-2,text.y-2,text.width+3,text.height+3);}}protected void paintContentBorder(Graphics g,int p,int s){}protected void paintText(Graphics g,int place,Font f,FontMetrics fm,int index,String title,Rectangle rect,boolean selected){g.setFont(f);g.setColor(selected?Color.WHITE:tabPane.getForegroundAt(index));g.drawString(title,rect.x,rect.y+fm.getAscent());}});p.setForeground(new Color(75,60,102));p.setOpaque(false);}
 public static void scroll(JScrollPane p){p.setBorder(new EmptyBorder(0,0,0,0));p.getViewport().setBackground(Color.WHITE);p.getVerticalScrollBar().setPreferredSize(new Dimension(16,0));p.getVerticalScrollBar().setUI(new BasicScrollBarUI(){protected void configureScrollBarColors(){thumbColor=new Color(141,111,194);trackColor=new Color(247,247,253);}protected JButton createDecreaseButton(int o){return vacio();}protected JButton createIncreaseButton(int o){return vacio();}private JButton vacio(){JButton b=new JButton();b.setPreferredSize(new Dimension(0,0));return b;}protected void paintThumb(Graphics g,JComponent c,Rectangle r){if(r.isEmpty())return;Graphics2D a=(Graphics2D)g.create();a.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);a.setColor(thumbColor);a.fillRoundRect(r.x+3,r.y,r.width-6,r.height,10,10);a.dispose();}});}
}
